const KEY='steadily-v1';
const localDay=(date=new Date())=>`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;
let today=localDay();
let state={profile:null,habits:[],logs:{},checks:{},challenge:[]};let storageError=false;
try{const raw=localStorage.getItem(KEY);if(raw){const parsed=JSON.parse(raw);if(!Array.isArray(parsed.habits)||!parsed.logs||!parsed.checks||!Array.isArray(parsed.challenge))throw Error('Invalid saved data');state=parsed}}catch{storageError=true}
let page='today',step=1,selected=['Move more','Read & learn'],barrier='Distraction',drafts=[];
const presets={'Move more':['Take a walk','Walk for 15 minutes','Step outside for 2 minutes','↗'],'Read & learn':['Read a few pages','Read for 10 minutes','Read one page','▤'],'Better sleep':['Wind down','Put my phone away 30 minutes before bed','Put my phone away for 5 minutes','☾'],'Less scrolling':['A screen-free morning','Wait 20 minutes before social media','Wait 2 minutes before social media','◷'],'Study & focus':['Make room to focus','Study for 25 minutes','Open my notes for 2 minutes','◎'],'Something else':['My small habit','Spend 10 minutes on my goal','Spend 1 minute on my goal','✧']};
const tasks=[['A slower start','Wait 10 minutes after waking before opening social media.'],['One mindful meal','Enjoy one meal without a screen. Notice the food and your surroundings.'],['Take the scenic route','Take a 5-minute walk with your phone put away.'],['Turn a few pages','Read a book or magazine for 10 minutes.'],['Make something just because','Spend 10 minutes on an offline hobby.'],['A little room for quiet','Sit outside or by a window for 5 minutes without entertainment.'],['Keep what felt good','Repeat your favorite offline activity from this week.']];
const reasons=['Tiredness','Insufficient time','Distraction','Forgetting','Excessive difficulty'];
const suggestions={'Tiredness':'Let the minimum version be enough. Try it at the time of day you usually have more energy.','Insufficient time':'Reserve two minutes after something you already do, such as breakfast. Start with the minimum version.','Distraction':'Put your phone out of reach before you begin. Make the first two minutes screen-free.','Forgetting':'Attach this habit to a familiar routine and choose a time you can remember.','Excessive difficulty':'Make the normal version smaller. Keep a minimum version that feels possible on a hard day.'};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageError=false}catch{storageError=true;toast('Your browser could not save this change. Keep this page open.')}}
function toast(text){const el=document.getElementById('toast');el.textContent=text;el.style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.style.display='none',4500)}
const log=(id,day=today)=>state.logs[day]?.[id];
const completed=v=>v?.type==='normal'||v?.type==='minimum';
function setHabit(id,type){if(!state.habits.some(h=>h.id===id)||!['normal','minimum','missed'].includes(type))throw Error('Invalid habit completion');state.logs[today]??={};state.logs[today][id]={...state.logs[today][id],type};save();render();toast(type==='minimum'?'Small counts. You showed up.':type==='normal'?'One small step, taken.':'There is room to begin again.');}
function recentDays(n=7){return Array.from({length:n},(_,i)=>{const d=new Date();d.setDate(d.getDate()-(n-1-i));return localDay(d)})}
function stats(){let normal=0,minimum=0,total=0,returns=0,returnDays=[];for(const h of state.habits){let gap=null,seen=false;for(let d=new Date(h.created+'T12:00:00');localDay(d)<=today;d.setDate(d.getDate()+1)){const key=localDay(d),v=log(h.id,key);total++;if(completed(v)){v.type==='normal'?normal++:minimum++;if(gap){returns++;returnDays.push(Math.round((new Date(key+'T12:00:00')-new Date(gap+'T12:00:00'))/86400000));gap=null}seen=true}else if((key<today||v?.type==='missed')&&seen&&!gap)gap=key;}}return {normal,minimum,total,returns,returnDays}}
function nav(p){page=p;render();window.scrollTo(0,0)}
function onboarding(){return `<main class="onboard"><div class="brand"><i class="mark"></i>steadily</div><span class="eyebrow">A little at a time · Step ${step} of 2</span><h1>${step===1?'Make room for a small beginning.':'Make it easy to show up.'}</h1><p class="muted">${step===1?'Choose what matters to you. We’ll start with a few things that fit your life.':'Every habit gets a smaller version for the days when life happens.'}</p><div class="card">${step===1?`<label for="name">What should we call you? <span class="muted">(optional)</span></label><input id="name" maxlength="40" placeholder="Your first name" value="${esc(window.draftName||'')}"><label>What would you like to work on? Choose 1–5.</label><div class="choices">${Object.keys(presets).map(x=>`<button data-goal="${esc(x)}" class="${selected.includes(x)?'active':''}" aria-pressed="${selected.includes(x)}">${x}</button>`).join('')}</div><label for="barrier">What most often gets in your way?</label><select id="barrier">${['Distraction','Tiredness','Insufficient time','Forgetting','Excessive difficulty'].map(x=>`<option ${barrier===x?'selected':''}>${x}</option>`).join('')}</select><div class="stepfoot"><small>Start with 1–3. Five is the maximum.</small><button class="primary" id="next" ${!selected.length?'disabled':''}>Shape my habits →</button></div>`:`<form id="startform">${drafts.map((h,i)=>`<div class="onhabit"><label for="title${i}">Habit ${i+1}</label><input id="title${i}" name="title${i}" value="${esc(h.title)}" required maxlength="80"><div class="formgrid"><div><label for="normal${i}">Normal version</label><input id="normal${i}" name="normal${i}" value="${esc(h.normal)}" required maxlength="160"></div><div><label for="minimum${i}">Minimum version</label><input id="minimum${i}" name="minimum${i}" value="${esc(h.minimum)}" required maxlength="160"></div></div><label for="time${i}">Best time</label><select id="time${i}" name="time${i}">${['Morning','Afternoon','Evening','Anytime'].map(t=>`<option ${t===h.time?'selected':''}>${t}</option>`).join('')}</select></div>`).join('')}<div class="callout">A minimum version counts as showing up. Your progress stays with you after a missed day.</div><p class="note">Your habits and check-ins are saved only in this browser. No account or syncing. Clearing browser data removes them.</p><div class="stepfoot"><button type="button" id="back">← Back</button><button class="primary">Begin my first day →</button></div></form>`}</div></main>`}
function shell(content){return `<div class="app"><aside class="sidebar"><div class="brand"><i class="mark"></i>steadily</div><div class="tagline">Small steps. Your pace.</div><nav class="nav" aria-label="Main navigation">${[['today','◫','My day'],['progress','▥','My progress'],['challenge','◷','Offline reset'],['habits','☷','My habits']].map(([id,icon,title])=>`<button data-nav="${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}><span>${icon}</span>${title}</button>`).join('')}</nav><div class="sidebottom"><p>Growth has room<br>for imperfect days.</p><div class="row"><span class="avatar">${esc((state.profile.name||'You')[0].toUpperCase())}</span><small>${esc(state.profile.name||'Your space')}</small><span>✧</span></div></div></aside><main class="main"><div class="topline"><span>${new Date().toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric'})}</span><span>YOUR PERSONAL SPACE</span></div>${storageError?'<div class="callout" role="alert">Browser storage is unavailable or saved data could not be loaded. Changes may not persist.</div>':''}${content}<p class="quote">Progress is something you return to, not something you lose.</p></main></div>`}
function weekChart(){return `<div class="week">${recentDays().map(d=>{const hs=state.habits.filter(h=>h.created<=d),n=hs.filter(h=>completed(log(h.id,d))).length;return `<div class="weekcol"><div class="bartrack" title="${d}: ${n} of ${hs.length} habits completed"><div class="bar" style="height:${hs.length?n/hs.length*100:0}%"></div></div>${new Date(d+'T12:00:00').toLocaleDateString('en-US',{weekday:'short'}).slice(0,1)}${d===today?' •':''}</div>`}).join('')}</div>`}
function habitCard(h){const v=log(h.id);return `<div class="habit"><div class="habithead"><span class="habiticon">${completed(v)?'✓':h.icon}</span><div style="flex:1"><div class="row"><h3>${esc(h.title)}</h3><small>${esc(h.time)}</small></div><p>${esc(h.normal)}</p>${completed(v)?`<div class="status">${v.type==='minimum'?'Minimum version':'Normal version'} completed · <button class="textbutton" data-undo="${h.id}">Undo</button></div>`:v?.type==='missed'?`<div class="status">A day to adjust · ${esc(v.reason||'Try a smaller step')}</div>`:''}</div></div><div class="actions"><button class="${v?.type==='normal'?'active':''}" data-complete="${h.id}" data-type="normal">${v?.type==='normal'?'✓ ':''}Normal</button><button class="${v?.type==='minimum'?'active':''}" data-complete="${h.id}" data-type="minimum" title="${esc(h.minimum)}">${v?.type==='minimum'?'✓ ':''}Minimum</button><button class="textbutton" data-recover="${h.id}">Having a hard day?</button></div></div>`}
function challengeCard(){const n=state.challenge.length,task=tasks[Math.min(n,6)],already=state.challenge.some(c=>c.date===today);return `<div class="card challenge"><span class="eyebrow">7 days of a little less noise</span><h2>${n===7?'More room for what matters.':task[0]}</h2><p>${n===7?'You explored seven ways to spend time offline. Keep the one that made your day feel better.':task[1]}</p><div class="days">${tasks.map((_,i)=>`<span class="daydot ${i<n?'done':i===n?'current':''}">${i<n?'✓':i+1}</span>`).join('')}</div><div class="row"><small>${n}/7 activities complete</small><button class="small" data-challenge ${n===7||already?'disabled':''}>${n===7?'Completed':already?'See you tomorrow':'I tried it →'}</button></div>${already&&n<7?'<p class="note">One activity is enough today. Your next one will be here tomorrow.</p>':''}</div>`}
function dayPage(){const n=state.habits.filter(h=>completed(log(h.id))).length,focus=state.habits.find(h=>h.id===state.profile.priority)||state.habits[0],check=state.checks[today];return `<div class="heading"><div><h1>A little better, at your pace.</h1><p>${state.profile.name?`${esc(state.profile.name)}, `:''}you don’t have to do it all. Just take the next small step.</p></div><button id="checkin">${check?'✓ Check-in saved':'☾ Evening check-in'}</button></div><div class="grid"><div class="stack"><section class="card focus"><div class="row"><span class="eyebrow">✧ Today’s one important thing</span><span class="badge">${esc(focus.time)}</span></div><h2>${esc(focus.title)}</h2><p>${esc(focus.normal)}. If today feels full, ${esc(focus.minimum.charAt(0).toLowerCase()+focus.minimum.slice(1))}.</p><button class="primary" data-complete="${focus.id}" data-type="minimum" ${completed(log(focus.id))?'disabled':''}>${completed(log(focus.id))?'✓ You showed up':'Take the small step →'}</button></section><section class="card"><div class="sectiontitle"><h2>Your small steps</h2><small>${n} of ${state.habits.length} today</small></div>${state.habits.map(habitCard).join('')}<div class="progressline"><span style="width:${n/state.habits.length*100}%"></span></div><p class="note">${n===state.habits.length?'You made room for yourself today. That is enough.':'The minimum version counts. Some effort is still effort.'}</p></section><section class="card row wrap"><div><h3 style="margin-bottom:5px">A moment to notice.</h3><small>${check?'Your reflection is saved. Come back whenever you need.':'How did today feel? A quick check-in helps you find your rhythm.'}</small></div><button id="finishday">${check?'View check-in':'Finish my day →'}</button></section></div><div class="stack rightstack">${challengeCard()}<section class="card"><div class="sectiontitle"><h2>Your week, gently.</h2><span>↗</span></div>${weekChart()}<p class="note">Each filled bar is a day you showed up. Empty days don’t erase the others.</p><button class="textbutton" data-nav="progress" style="margin-top:12px">See my progress →</button></section><section class="card"><span class="eyebrow">A small suggestion</span><p style="margin:12px 0 0">${esc(recommendation())}</p></section></div></div>`}
function recommendation(){const checks=Object.entries(state.checks).sort((a,b)=>b[0].localeCompare(a[0])).slice(0,7);if(checks.length>=3&&checks.filter(([,c])=>c.energy<=2).length>=2)return 'You recorded low energy on at least two recent days. Try your minimum versions and move one habit to an easier time.';const all=Object.entries(state.logs).sort((a,b)=>b[0].localeCompare(a[0])).flatMap(([,v])=>Object.values(v)).filter(v=>v.reason);return all.length?suggestions[all[0].reason]:suggestions[state.profile.barrier]}
function progressPage(){const s=stats(),checks=Object.entries(state.checks).sort((a,b)=>b[0].localeCompare(a[0])).slice(0,7);return `<div class="heading"><div><h1>Look how you’re showing up.</h1><p>Your whole journey counts, including the days you begin again.</p></div></div><div class="metrics"><div class="card"><span class="stat">${s.total?Math.round((s.normal+s.minimum)/s.total*100):0}%</span><p>Habit completion</p></div><div class="card"><span class="stat">${s.normal} <small>/ ${s.minimum}</small></span><p>Normal / minimum</p></div><div class="card"><span class="stat">${s.returns}</span><p>Times you returned</p></div></div><div class="grid"><div class="stack"><section class="card"><h2>The last seven days</h2>${weekChart()}<p class="note">Normal and minimum versions both count. Rates include each planned day from the day you added a habit, including today.</p></section><section class="card"><h2>Your recent check-ins</h2>${checks.length?`<table class="history"><thead><tr><th>Day</th><th>Mood</th><th>Energy</th><th>Stress</th></tr></thead><tbody>${checks.map(([d,c])=>`<tr><td>${new Date(d+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric'})}</td><td>${c.mood}/5</td><td>${c.energy}/5</td><td>${c.stress}/5</td></tr>`).join('')}</tbody></table><p class="note">1 is low · 5 is high</p>`:'<p class="empty">Your first check-in starts the story. You don’t need a full week to begin.</p>'}</section></div><div class="stack"><section class="card focus"><span class="eyebrow">Your next gentle adjustment</span><p style="margin:16px 0 0">${esc(recommendation())}</p></section><section class="card"><h2>Returning is progress.</h2><p>${s.returns?`You have returned ${s.returns} time${s.returns===1?'':'s'} after a gap. Your average time back is ${(s.returnDays.reduce((a,b)=>a+b,0)/s.returns).toFixed(1)} days.`:'When you complete a habit after a missed day, your return will appear here. There’s no streak to protect.'}</p><small>A return means showing up again after at least one missed planned day.</small></section>${checks.filter(([,c])=>c.win).length?`<section class="card"><h2>Wins worth keeping</h2>${checks.filter(([,c])=>c.win).map(([d,c])=>`<p>${esc(c.win)}<br><small>${d}</small></p>`).join('')}</section>`:''}</div></div>`}
function challengePage(){return `<div class="heading"><div><h1>A little less noise.</h1><p>Seven small invitations to spend time offline. No rush, no restart.</p></div></div><div class="grid"><div class="stack">${challengeCard()}<section class="card"><h2>Your seven invitations</h2>${tasks.map(([title,desc],i)=>`<div class="habit"><div class="row"><h3>${i+1}. ${title}</h3><span>${state.challenge[i]?'✓':''}</span></div><p>${desc}</p>${state.challenge[i]?`<p class="status">Difficulty ${state.challenge[i].difficulty}/5 · Enjoyment ${state.challenge[i].enjoyment}/5</p>`:''}</div>`).join('')}</section></div><aside class="stack"><div class="card"><h2>Make room for real life.</h2><p>This isn’t a medical “dopamine reset.” It’s an experiment in noticing how simple, screen-free moments feel.</p><p class="muted">Try one activity a day. If you miss a day, continue where you left off. There is no timer to beat.</p></div></aside></div>`}
function habitsPage(){return `<div class="heading"><div><h1>Small enough for real life.</h1><p>Adjust your habits as you learn what works.</p></div><button class="primary" id="addhabit" ${state.habits.length>=5?'disabled':''}>+ Add habit</button></div><div class="stack">${state.habits.map(h=>`<section class="card"><div class="row wrap"><div><span class="eyebrow">${esc(h.time)} ${state.profile.priority===h.id?'· Today’s priority':''}</span><h2 style="margin-top:10px">${esc(h.title)}</h2><p style="margin-bottom:5px">${esc(h.normal)}</p><small>Minimum: ${esc(h.minimum)}</small></div><div class="row wrap"><button class="small" data-priority="${h.id}">Make priority</button><button class="small" data-edit="${h.id}">Edit habit</button></div></div></section>`).join('')}<p class="note">${state.habits.length}/5 habits. Keeping your list small leaves room to actually live it.</p></div>`}
function render(){today=localDay();document.getElementById('app').innerHTML=state.profile?shell(page==='today'?dayPage():page==='progress'?progressPage():page==='challenge'?challengePage():habitsPage()):onboarding();bind()}
function modal(body){document.querySelector('dialog')?.remove();const d=document.createElement('dialog');d.innerHTML=`<button class="close" aria-label="Close">×</button>${body}`;document.body.append(d);d.querySelector('.close').onclick=()=>d.close();d.addEventListener('close',()=>d.remove());d.showModal();return d}
function recovery(id){const h=state.habits.find(h=>h.id===id);const d=modal(`<h2>Let’s make this a little easier.</h2><p class="muted">${esc(h.title)} can wait, shrink, or move. What got in the way?</p><div class="choices">${reasons.map(r=>`<button data-reason="${r}">${r}</button>`).join('')}</div><div id="suggestion"></div>`);d.querySelectorAll('[data-reason]').forEach(b=>b.onclick=()=>{const reason=b.dataset.reason;state.logs[today]??={};state.logs[today][id]={type:'missed',reason};save();render();d.querySelectorAll('[data-reason]').forEach(x=>x.classList.toggle('active',x===b));d.querySelector('#suggestion').innerHTML=`<div class="callout">${suggestions[reason]}</div><p class="note">Minimum: ${esc(h.minimum)}</p><button class="primary full" id="trymin">I did the minimum version</button><button class="full" id="adjust">Adjust this habit</button><button class="textbutton full" id="leave">Leave it for today</button>`;d.querySelector('#trymin').onclick=()=>{setHabit(id,'minimum');d.close()};d.querySelector('#adjust').onclick=()=>{d.close();editHabit(id)};d.querySelector('#leave').onclick=()=>{d.close();toast('Your progress is still here. Begin again when you can.')}})}
function range(name,label,value=3){return `<label for="${name}">${label} <output id="${name}out">${value}</output>/5</label><input type="range" min="1" max="5" id="${name}" name="${name}" value="${value}" oninput="document.getElementById('${name}out').textContent=this.value"><div class="rating"><span>Low</span><span>High</span></div>`}
function checkin(){const c=state.checks[today]||{},pending=state.habits.filter(h=>!completed(log(h.id)));const d=modal(`<h2>How did today feel?</h2><p class="muted">A quick pause. No perfect answers.</p><form id="checkform">${range('mood','Mood',c.mood||3)}${range('energy','Energy',c.energy||3)}${range('stress','Stress',c.stress||3)}<label for="win">One small win <span class="muted">(optional)</span></label><input id="win" name="win" maxlength="240" value="${esc(c.win||'')}" placeholder="I got outside for a few minutes">${pending.map(h=>`<label for="reason${h.id}">What got in the way of ${esc(h.title.toLowerCase())}?</label><select id="reason${h.id}" name="reason${h.id}" required><option value="">Choose a reason</option>${reasons.map(r=>`<option ${log(h.id)?.reason===r?'selected':''}>${r}</option>`).join('')}</select>`).join('')}<button class="primary full">Save my check-in</button></form>`);d.querySelector('form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);state.checks[today]={mood:+f.get('mood'),energy:+f.get('energy'),stress:+f.get('stress'),win:f.get('win').trim()};state.logs[today]??={};pending.forEach(h=>state.logs[today][h.id]={type:'missed',reason:f.get('reason'+h.id)});save();render();d.close();modal(`<span class="eyebrow">Today is enough</span><h2 style="margin-top:15px">Thank you for showing up.</h2><p>You took a moment to notice your day. Your progress is safe, even when things didn’t go to plan.</p>${pending.length?`<div class="callout">${esc(recommendation())}</div>`:''}<button class="primary full" id="donecheck">Close and enjoy your evening</button>`).querySelector('#donecheck').onclick=()=>document.querySelector('dialog').close()}}
function editHabit(id){const h=state.habits.find(h=>h.id===id)||{title:'',normal:'',minimum:'',time:'Anytime',icon:'✧'};if(!id&&state.habits.length>=5)return;const d=modal(`<h2>${id?'Adjust your habit':'One more small step'}</h2><form><label for="title">Habit</label><input id="title" name="title" required maxlength="80" value="${esc(h.title)}"><label for="normal">Normal version</label><input id="normal" name="normal" required maxlength="160" value="${esc(h.normal)}"><label for="minimum">Minimum version</label><input id="minimum" name="minimum" required maxlength="160" value="${esc(h.minimum)}"><label for="time">Best time</label><select name="time" id="time">${['Morning','Afternoon','Evening','Anytime'].map(t=>`<option ${h.time===t?'selected':''}>${t}</option>`).join('')}</select><button class="primary full">Save habit</button></form>`);d.querySelector('form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),values=Object.fromEntries(f);if(!values.title.trim()||!values.normal.trim()||!values.minimum.trim())return;Object.assign(h,values);if(!id)state.habits.push({...h,id:crypto.randomUUID(),created:today});save();render();d.close();toast('Your plan can grow with you.')}}
function rateChallenge(){if(state.challenge.length>=7||state.challenge.some(c=>c.date===today))return;const d=modal(`<h2>What was that like?</h2><p>${tasks[state.challenge.length][0]}</p><form>${range('difficulty','Difficulty')}${range('enjoyment','Enjoyment')}<button class="primary full">Save today’s activity</button></form>`);d.querySelector('form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);state.challenge.push({date:today,difficulty:+f.get('difficulty'),enjoyment:+f.get('enjoyment')});save();render();d.close();toast('A little more room for life offline.')}}
function bind(){document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>nav(b.dataset.nav));document.querySelectorAll('[data-complete]').forEach(b=>b.onclick=()=>setHabit(b.dataset.complete,b.dataset.type));document.querySelectorAll('[data-undo]').forEach(b=>b.onclick=()=>{delete state.logs[today][b.dataset.undo];save();render()});document.querySelectorAll('[data-recover]').forEach(b=>b.onclick=()=>recovery(b.dataset.recover));document.querySelectorAll('[data-challenge]').forEach(b=>b.onclick=rateChallenge);document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editHabit(b.dataset.edit));document.querySelectorAll('[data-priority]').forEach(b=>b.onclick=()=>{state.profile.priority=b.dataset.priority;save();render();toast('Your one important thing is updated.')});['checkin','finishday'].forEach(id=>{const b=document.getElementById(id);if(b)b.onclick=checkin});const add=document.getElementById('addhabit');if(add)add.onclick=()=>editHabit();document.querySelectorAll('[data-goal]').forEach(b=>b.onclick=()=>{window.draftName=document.getElementById('name').value;barrier=document.getElementById('barrier').value;const g=b.dataset.goal;if(selected.includes(g))selected=selected.filter(x=>x!==g);else if(selected.length<5)selected.push(g);else toast('Five is plenty to begin with.');render()});const next=document.getElementById('next');if(next)next.onclick=()=>{window.draftName=document.getElementById('name').value.trim();barrier=document.getElementById('barrier').value;drafts=selected.map(g=>{const [title,normal,minimum,icon]=presets[g];return {title,normal,minimum,icon,time:g==='Better sleep'?'Evening':'Morning'}});step=2;render();window.scrollTo(0,0)};const back=document.getElementById('back');if(back)back.onclick=()=>{step=1;render()};const start=document.getElementById('startform');if(start)start.onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);if(drafts.some((h,i)=>['title','normal','minimum'].some(k=>!f.get(k+i).trim())))return;state.habits=drafts.map((h,i)=>({...h,id:crypto.randomUUID(),title:f.get('title'+i).trim(),normal:f.get('normal'+i).trim(),minimum:f.get('minimum'+i).trim(),time:f.get('time'+i),created:today}));state.profile={name:window.draftName||'',barrier,priority:state.habits[0].id};save();render();window.scrollTo(0,0)}}
render();
